create table xxventuri.crm_accounts_t (
    account_id       number,
    account_name     varchar2(200 char) not null enable,
    account_type     varchar2(50 char),
    industry         varchar2(100 char),
    website          varchar2(500 char),
    phone            varchar2(50 char),
    email            varchar2(255 char),
    billing_address  varchar2(500 char),
    shipping_address varchar2(500 char),
    annual_revenue   number(15, 2),
    owner_id         number not null enable,
    status_code      varchar2(20 char) default 'ACTIVE' not null enable,
    row_version      number default 0 not null enable,
    created_by       varchar2(100 char) not null enable,
    created_date     timestamp(6) not null enable,
    updated_by       varchar2(100 char) not null enable,
    updated_date     timestamp(6) not null enable
);

alter table xxventuri.crm_accounts_t
    add constraint crm_accounts_pk primary key ( account_id )
        using index enable;

alter table xxventuri.crm_accounts_t
    add constraint crm_accounts_status_chk
        check ( status_code in ( 'ACTIVE', 'INACTIVE' ) ) enable;


